[
  {
    "statement": "Very limited evidence exists for the effectiveness of strategies to combat white-nose syndrome in bats.",
    "citations": []
  },
  {
    "statement": "The only strategy with documented evidence is treating bats with probiotic bacteria.",
    "citations": [
      "2008"
    ]
  },
  {
    "statement": "Two studies evaluated the effects of treating bats with probiotic bacteria.",
    "citations": [
      "2008"
    ]
  },
  {
    "statement": "A randomized, controlled study in Canada found that treating little brown bats with a probiotic bacterium at the time of infection with white-nose syndrome increased survival within cages in a laboratory.",
    "citations": [
      "2008"
    ]
  },
  {
    "statement": "A randomized, controlled study in the USA found that treating little brown bats with a probiotic bacterium within a mine increased survival for free-flying bats.",
    "citations": [
      "2008"
    ]
  },
  {
    "statement": "The randomized, controlled study in the USA found that treating little brown bats with a probiotic bacterium within a mine did not increase survival for caged bats.",
    "citations": [
      "2008"
    ]
  },
  {
    "statement": "The Canadian study found that little brown bats treated with a probiotic bacterium at the time of infection had reduced symptoms of white-nose syndrome.",
    "citations": [
      "2008"
    ]
  },
  {
    "statement": "The Canadian study found that bats treated with a probiotic bacterium 21 days prior to infection had worse symptoms of white-nose syndrome.",
    "citations": [
      "2008"
    ]
  },
  {
    "statement": "The USA study found that little brown bats kept within cages in a mine and treated with a probiotic bacterium had a similar severity of white-nose syndrome to untreated bats.",
    "citations": [
      "2008"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of culling infected bats.",
    "citations": [
      "1012"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of vaccination against the pathogen that causes white-nose syndrome.",
    "citations": [
      "1011"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of captive breeding to supplement affected bat populations.",
    "citations": [
      "2009"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of treating hibernacula environments to reduce the pathogen reservoir.",
    "citations": [
      "2007"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of decontaminating clothing and equipment.",
    "citations": [
      "2006"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of restricting human access to caves.",
    "citations": [
      "1010"
    ]
  }
]

[
  {
    "statement": "Several types of crossing structures can be installed to help bats cross roads and railways safely.",
    "citations": []
  },
  {
    "statement": "Green bridges show promise as a crossing structure for bats.",
    "citations": [
      "979"
    ]
  },
  {
    "statement": "One study in the UK found that a green bridge was used by 97% of bats crossing a road.",
    "citations": [
      "979"
    ]
  },
  {
    "statement": "Underpasses and culverts are widely used as crossing structures for bats.",
    "citations": [
      "976"
    ]
  },
  {
    "statement": "Studies across Germany, Ireland, the UK, Australia and France found that bats used underpasses and culverts below roads in varying proportions.",
    "citations": [
      "976"
    ]
  },
  {
    "statement": "Bat use of underpasses and culverts is influenced by underpass type and height, road width, and surrounding landscape features.",
    "citations": [
      "976"
    ]
  },
  {
    "statement": "Overpasses are another option for bat crossing structures.",
    "citations": [
      "977"
    ]
  },
  {
    "statement": "Studies in Ireland and France found that two or three bat species used overpasses.",
    "citations": [
      "977"
    ]
  },
  {
    "statement": "Despite the presence of overpasses, studies found that up to three-quarters of bats still crossed at traffic height or at other nearby locations.",
    "citations": [
      "977"
    ]
  },
  {
    "statement": "One UK study found that an overpass with planters was used by two-thirds of crossing bats.",
    "citations": [
      "977"
    ]
  },
  {
    "statement": "A UK study found that an unvegetated overpass was not used by bats.",
    "citations": [
      "977"
    ]
  },
  {
    "statement": "Bat gantries or bat bridges have shown mixed results as safe crossing structures.",
    "citations": [
      "978"
    ]
  },
  {
    "statement": "UK studies found that fewer bats used gantries than crossed below the structures at traffic height.",
    "citations": [
      "978"
    ]
  },
  {
    "statement": "One bat gantry in a UK study was not used at all.",
    "citations": [
      "978"
    ]
  },
  {
    "statement": "A French study found that a temporary gantry was used by three bat species.",
    "citations": [
      "978"
    ]
  },
  {
    "statement": "In a French study, almost half of crossing bats flew over the road at other locations instead of using a temporary gantry.",
    "citations": [
      "978"
    ]
  },
  {
    "statement": "Bats can be diverted to safe crossing points using plantings or fencing.",
    "citations": [
      "981"
    ]
  },
  {
    "statement": "One controlled study in Switzerland found that up to one-fifth of lesser horseshoe bats flew along an artificial hedgerow to commute.",
    "citations": [
      "981"
    ]
  }
]

[
  {
    "statement": "Based on research studies, the most effective operational adjustments to wind turbines to reduce bat fatalities include three main approaches.",
    "citations": []
  },
  {
    "statement": "Increasing the wind speed at which turbines become operational, known as the cut-in speed, has been found to result in fewer bat fatalities compared to conventionally operated turbines.",
    "citations": [
      "1960"
    ]
  },
  {
    "statement": "Preventing turbine blades from turning at low wind speeds is a practice known as 'feathering'.",
    "citations": [
      "970"
    ]
  },
  {
    "statement": "Studies have found that feathering turbine blades resulted in fewer bat fatalities than at conventionally operated turbines.",
    "citations": [
      "970"
    ]
  },
  {
    "statement": "A study found that bat fatalities were reduced when turbine blades were slowed at low wind speeds.",
    "citations": [
      "2939"
    ]
  },
  {
    "statement": "Operational adjustments to reduce bat fatalities focus on reducing turbine activity during low wind conditions.",
    "citations": []
  },
  {
    "statement": "Bats are most active and vulnerable to turbine strikes during low wind conditions.",
    "citations": []
  }
]

[
  {
    "statement": "Several non-lethal alternatives to culling can be used to manage human-bat conflicts.",
    "citations": []
  },
  {
    "statement": "For fruit orchard protection, effective measures include using organic deterrent sprays and hanging plastic flags in trees.",
    "citations": [
      "1953"
    ]
  },
  {
    "statement": "Covering individual tree branches with nylon net bags can reduce damage to lychees caused by Madagascan flying foxes or Mauritius fruit bats.",
    "citations": [
      "1953"
    ]
  },
  {
    "statement": "Ringing bells in lychee trees can deter most Madagascan flying foxes.",
    "citations": [
      "1953"
    ]
  },
  {
    "statement": "For wind turbine conflicts, ultrasonic deterrents can reduce bat fatalities.",
    "citations": [
      "968"
    ]
  },
  {
    "statement": "Some studies found 21-51% fewer bats were killed at turbines with ultrasonic deterrents, though results were mixed across different species and study years.",
    "citations": [
      "968"
    ]
  },
  {
    "statement": "Roost management approaches include creating alternative bat roosts within developments.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Purpose-built roosts like bat boxes or bat lofts/barns were used by bats at 13-74% of development sites.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "New bat roosts were four times less likely to be used than retained roosts.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "One study found that excluding bats from roosts within buildings did not change roost switching frequency or foraging behaviors of soprano pipistrelle colonies.",
    "citations": [
      "1930"
    ]
  },
  {
    "statement": "Non-lethal methods can replace culling for preventing vampire bats from spreading rabies to livestock and humans.",
    "citations": [
      "1950",
      "1979"
    ]
  },
  {
    "statement": "Educating farmers and communities can help to reduce indiscriminate culling of bats.",
    "citations": [
      "2044"
    ]
  },
  {
    "statement": "No studies were found that directly evaluated replacing culling with non-lethal methods for preventing vampire bat-spread rabies or educating communities to reduce culling.",
    "citations": [
      "1950",
      "1979",
      "2044"
    ]
  }
]

[
  {
    "statement": "Several alternative lighting strategies can be used to minimize disturbance to bats beyond avoiding illumination entirely.",
    "citations": []
  },
  {
    "statement": "Red lighting shows promise as an alternative lighting strategy.",
    "citations": []
  },
  {
    "statement": "Studies found that more soprano pipistrelles emerged from a roost when the roost was lit with red light than when it was lit with white light.",
    "citations": [
      "2021"
    ]
  },
  {
    "statement": "One study found that using low intensity white lights or red lights in caves resulted in fewer bat flights than with full white lighting.",
    "citations": [
      "1994"
    ]
  },
  {
    "statement": "Ultraviolet filtering is an effective strategy for minimizing bat disturbance.",
    "citations": []
  },
  {
    "statement": "One study found that hedges lit with ultraviolet filtered lights had higher soprano pipistrelle activity than hedges lit with unfiltered light.",
    "citations": [
      "1020"
    ]
  },
  {
    "statement": "Shielding lights can reduce the impacts of illumination on bats.",
    "citations": []
  },
  {
    "statement": "Studies on shielded \"full cut-off\" lights showed that fewer individual moths and moth species were attracted to lights fitted with blinds and filters than to conventional lights.",
    "citations": [
      "3904"
    ]
  },
  {
    "statement": "The attraction of insects to lights is relevant for bats since many bat species feed on these insects.",
    "citations": []
  },
  {
    "statement": "It is important to avoid illuminating specific areas used by bats, particularly their commuting routes.",
    "citations": []
  },
  {
    "statement": "Research showed that 28-96% of pond bats changed their flight paths along canals to avoid light spill from lamps.",
    "citations": [
      "2017"
    ]
  },
  {
    "statement": "Lesser horseshoe bats and myotis bats had greater activity along unlit hedges than along hedges illuminated with street lights.",
    "citations": [
      "2017"
    ]
  }
]

[
  {
    "statement": "Several specific actions can be taken to protect bats during and after mine closure and reclamation.",
    "citations": []
  },
  {
    "statement": "Research on the effectiveness of actions to protect bats during and after mine closure and reclamation is limited.",
    "citations": []
  },
  {
    "statement": "One action to protect bats involves retaining access points for the animals following mine closures.",
    "citations": [
      "1962"
    ]
  },
  {
    "statement": "Bats can be excluded from roosts prior to mine reclamation.",
    "citations": [
      "1961"
    ]
  },
  {
    "statement": "Entrances to closed mines can be reopened and made suitable for roosting bats.",
    "citations": [
      "1965"
    ]
  },
  {
    "statement": "Maintaining the microclimate in closed or abandoned mines is an approach to protect bats.",
    "citations": [
      "1964"
    ]
  },
  {
    "statement": "A study in the USA found that modifying the microclimate of an abandoned mine by closing a man-made entrance resulted in a greater number of bats hibernating within the mine.",
    "citations": [
      "1964"
    ]
  },
  {
    "statement": "Providing artificial subterranean bat roosts to replace roosts in reclaimed mines is a potential mitigation measure.",
    "citations": [
      "974"
    ]
  },
  {
    "statement": "Relocating bats from reclaimed mines to alternative subterranean roost sites is a potential mitigation measure.",
    "citations": [
      "975"
    ]
  },
  {
    "statement": "Creating artificial caves or hibernacula for bats has shown some success.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "Studies in the UK and Germany found that artificial hibernacula were used by up to four bat species.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "The number of bats using an artificial hibernaculum increased in each of nine years after the hibernaculum was built.",
    "citations": [
      "2049"
    ]
  },
  {
    "statement": "Installing and maintaining gates at mine entrances to restrict public access while allowing bat access is a conservation approach.",
    "citations": [
      "1963"
    ]
  },
  {
    "statement": "Nine studies on mine gates found mixed results for bat conservation.",
    "citations": [
      "1963"
    ]
  },
  {
    "statement": "In one study, 43 of 47 mines continued to be used by bats 12 years after gates were installed.",
    "citations": [
      "1963"
    ]
  },
  {
    "statement": "Bats abandoned four mines that were fitted with 'ladder' design gates.",
    "citations": [
      "1963"
    ]
  },
  {
    "statement": "Gate installation resulted in fewer bat species entering mines.",
    "citations": [
      "1963"
    ]
  },
  {
    "statement": "Gate installation altered bat behavior at mine entrances.",
    "citations": [
      "1963"
    ]
  }
]

[
  {
    "statement": "Based on available evidence, the most effective legislative action for protecting bats and bat habitats is legally protecting bat habitats.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Studies show that protected areas generally have higher bat activity and species diversity compared to unprotected areas.",
    "citations": []
  },
  {
    "statement": "Four studies found higher overall bat activity in protected sites and forests than unprotected sites and forests.",
    "citations": []
  },
  {
    "statement": "Four studies found higher activity of three of six bat species or species groups in protected sites and forests than in unprotected sites and forests.",
    "citations": []
  },
  {
    "statement": "According to four studies, a greater number of bats were found in protected sites and forests than in unprotected sites and forests.",
    "citations": []
  },
  {
    "statement": "One study found that protected sites had a greater number of bat species than unprotected sites.",
    "citations": []
  },
  {
    "statement": "The activity of Daubenton's bats was higher over rivers on farms in protected areas than in unprotected areas.",
    "citations": []
  },
  {
    "statement": "Common noctule bat activity was higher in protected forests than in unprotected forests.",
    "citations": []
  },
  {
    "statement": "The distributions of 10 of 11 bat species overlapped with areas designated to protect those species significantly more than by chance.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of legally protecting bat species on bat populations.",
    "citations": [
      "2037"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of introducing legislation to control the hunting of bats on bat populations.",
    "citations": [
      "984"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of regulating bat guano harvesting on bat populations.",
    "citations": [
      "987"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effectiveness of enforcing regulations to prevent bat trafficking and trade on bat populations.",
    "citations": [
      "1971"
    ]
  }
]

[
  {
    "statement": "Creating spaces for roosting bats in road bridges has shown mixed success.",
    "citations": [
      "1967"
    ]
  },
  {
    "statement": "When spaces for roosting bats were created in road bridges, recolonization occurred at four of eight sites.",
    "citations": [
      "1967"
    ]
  },
  {
    "statement": "At sites where recolonization occurred, the number of bats was similar to or greater than the numbers in the original roosts.",
    "citations": [
      "1967"
    ]
  },
  {
    "statement": "When maintaining existing bat roosts during road bridge repair work, the results were species-specific.",
    "citations": [
      "1966"
    ]
  },
  {
    "statement": "A maternity colony of Daubenton's bats continued to roost in similar numbers after crevices were retained in a bridge.",
    "citations": [
      "1966"
    ]
  },
  {
    "statement": "Yuma myotis and Mexican free-tailed bats recolonised most roosts in similar numbers after repair work.",
    "citations": [
      "1966"
    ]
  },
  {
    "statement": "Pallid bats did not return to roosts after bridge repair work.",
    "citations": [
      "1966"
    ]
  },
  {
    "statement": "A key limitation identified was that alternative bat roosts provided during bridge replacement works were significantly less effective than original roosts.",
    "citations": [
      "2942"
    ]
  },
  {
    "statement": "Bat houses provided as alternative roosts were used by fewer Mexican free-tailed bats than the original roost at one site.",
    "citations": [
      "2942"
    ]
  },
  {
    "statement": "At three sites, bat houses provided as alternative roosts were not used at all.",
    "citations": [
      "2942"
    ]
  },
  {
    "statement": "All documented studies on these conservation approaches were based on research in the USA and one study in Ireland.",
    "citations": []
  },
  {
    "statement": "The available evidence for providing or retaining bat roosts in transportation infrastructure has limited geographic coverage.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence for managing existing hedgerows for bats significantly outweighs the evidence for planting new hedges.",
    "citations": [
      "1943",
      "1942"
    ]
  },
  {
    "statement": "Two studies in the UK evaluated the effects of managing hedges to benefit bat populations.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "Hedges trimmed three or more years prior had more bat species recorded along them than hedges trimmed during the previous winter.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "Hedges trimmed three or more years prior had higher activity of two of eight bat species or species groups than recently trimmed hedges.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "One study found that pipistrelle activity did not differ between hedges managed for wildlife on agri-environment scheme farms and hedges on conventional farms.",
    "citations": [
      "1943"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of planting new hedges on bat populations.",
    "citations": [
      "1942"
    ]
  }
]

[
  {
    "statement": "One specific method for providing bat roosting sites in trees where natural cavities are lacking is to create artificial hollows and cracks in trees.",
    "citations": []
  },
  {
    "statement": "Artificial hollows can be cut into trees for bats.",
    "citations": [
      "2047"
    ]
  },
  {
    "statement": "One replicated study in Australia found that eight of 16 artificial hollows cut into trees with two different entrance designs were used by roosting long-eared bats.",
    "citations": [
      "2047"
    ]
  },
  {
    "statement": "Other potential actions for providing bat roosting sites include providing bat boxes, bat grilles, and improvements to roosts.",
    "citations": [
      "95"
    ]
  },
  {
    "statement": "No evidence was found for the effectiveness of providing bat boxes, bat grilles, and improvements to roosts on farmland wildlife.",
    "citations": [
      "95"
    ]
  },
  {
    "statement": "Retaining veteran and standing dead trees can provide roosting sites for bats.",
    "citations": [
      "993"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of retaining veteran and standing dead trees on bat populations.",
    "citations": [
      "993"
    ]
  },
  {
    "statement": "Artificial dens or nest boxes on trees were used by a range of mammal species for roosting and breeding.",
    "citations": [
      "2584"
    ]
  },
  {
    "statement": "Twenty-seven studies across multiple countries found use of artificial dens or nest boxes on trees by a range of mammal species.",
    "citations": [
      "2584"
    ]
  }
]

[
  {
    "statement": "The evidence for legally protecting bat habitats is substantially more comprehensive than for legally protecting bats during development activities.",
    "citations": [
      "2045",
      "1935"
    ]
  },
  {
    "statement": "For habitat protection, five studies evaluated effects on bat populations across Europe and India.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "These studies on habitat protection showed mixed but generally positive results.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Results included higher bat activity in protected areas.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Results included greater species numbers in some protected sites.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Results showed a significant overlap between bat distributions and designated protection areas.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Evidence for legal protection of bats during development comes from only four studies.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "All studies on legal protection during development were conducted in the UK.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "No studies on legal protection during development measured community or population responses.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "The development protection studies focused primarily on behavioral changes and impacts on roost sites.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Studies found that 68% of roosts were destroyed during licensed activities.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Only 31-67% of compensation roosts were actually used by bats.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "81% of licensees failed to conduct post-development monitoring.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "The habitat protection evidence demonstrates measurable ecological benefits.",
    "citations": [
      "2045"
    ]
  },
  {
    "statement": "Development protection evidence reveals implementation challenges.",
    "citations": [
      "1935"
    ]
  },
  {
    "statement": "Development protection evidence reveals limited effectiveness of compensation measures.",
    "citations": [
      "1935"
    ]
  }
]

[
  {
    "statement": "Based on twelve studies across Europe, the USA, Canada, and Chile, the effects of organic farming versus conventional farming on bat populations show mixed results.",
    "citations": []
  },
  {
    "statement": "Regarding species richness and diversity, five of seven studies found that the number of bat species did not differ between organic and non-organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Two studies found more bat species on organic farms than on non-organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "For bat abundance and activity, five of nine studies found that overall bat activity and common pipistrelle activity did not differ between organic and non-organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Four studies found higher overall bat activity, bat feeding activity, Brazilian free-tailed bat activity, and activity of four of seven bat species on organic farms than on non-organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Two UK studies found higher activity of Myotis species over water and rivers on organic farms than on non-organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Two UK studies found no differences in bat activity for other species or habitats between organic and non-organic farms.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "One French study found higher activity for two of three bat species over organic fields than over two of three types of conventionally managed fields.",
    "citations": [
      "961"
    ]
  },
  {
    "statement": "Farms with few or no chemical inputs had different compositions of bat species compared to farms using high chemical inputs.",
    "citations": [
      "2013",
      "2331"
    ]
  },
  {
    "statement": "Farms with few or no chemical inputs had higher overall bat activity compared to farms using high chemical inputs.",
    "citations": [
      "2013",
      "2331"
    ]
  },
  {
    "statement": "One study in Colombia found that great fruit-eating bats in silvopastoral areas with no chemicals had higher body weights and body condition scores than great fruit-eating bats in conventional farming areas using chemicals.",
    "citations": [
      "2013"
    ]
  }
]

[
  {
    "statement": "Several alternatives to bat exclusion during building developments have been studied to mitigate disturbance to roosts.",
    "citations": []
  },
  {
    "statement": "Creating alternative bat roosts within developments has been evaluated in eleven studies, showing mixed results.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Bat boxes or bat lofts were used by bats at 13-74% of development sites.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "In three of five studies, purpose-built roosts were used by bat colonies in higher or similar numbers compared to original roosts.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Two studies found lower usage of purpose-built roosts compared to original roosts.",
    "citations": [
      "949"
    ]
  },
  {
    "statement": "Retaining existing bat roosts and access points within developments has been studied.",
    "citations": [
      "947"
    ]
